class Solution:
    def nextLargerNodes(self, head):
        vals = []
        while head:
            vals.append(head.val)
            head = head.next
        result = [0] * len(vals)
        stack = []
        for i, val in enumerate(vals):
            while stack and vals[stack[-1]] < val:
                result[stack.pop()] = val
            stack.append(i)
        return result

